SELECT toJSONString(groupArray(tuple(t,timestamps,log_samples,min_hosts,max_hosts,memory_byte_samples,min_memory_bytes,max_memory_bytes))) AS payload FROM (SELECT toUnixTimestamp(toStartOfInterval(event_time,INTERVAL 5 MINUTE)) AS t,count() AS timestamps,sum(log_samples) AS log_samples,min(hosts) AS min_hosts,max(hosts) AS max_hosts,sum(metric) AS memory_byte_samples,min(metric) AS min_memory_bytes,max(metric) AS max_memory_bytes FROM (SELECT event_time,sum(CurrentMetric_MemoryTracking) AS metric,count() AS log_samples,uniqExact(hostname) AS hosts FROM clusterAllReplicas(default,merge('system','^metric_log')) WHERE event_date BETWEEN '2026-08-08' AND '2026-08-09' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-09 19:40:58','UTC') GROUP BY event_time) GROUP BY t ORDER BY t LIMIT 500) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000,skip_unavailable_shards=0;
